//! Load a WESL wisp that imports from a local module and from a package.
//!
//! `assets/wisp/test_wesl.wesl` imports a palette from the local module
//! `assets/wisp/lib/palette.wesl` and a circle from the `shapes` package
//! registered below. Run with `--features bevy/file_watcher` to live-edit
//! either file.

use bevy::prelude::*;
use bevy_wisp::link::{StaticPackage, StaticPackageModule};
use bevy_wisp::prelude::*;

/// A WESL package with one module, `shapes::circle`. Real packages are usually
/// generated by `wesl`'s `PackageBuilder` in a build script and included with
/// `wesl_pkg!`.
static SHAPES: StaticPackage = StaticPackage {
    crate_name: "shapes",
    root: &StaticPackageModule {
        name: "shapes",
        source: "",
        submodules: &[&StaticPackageModule {
            name: "circle",
            source: "public fn circle(p: vec2<f32>, r: f32) -> f32 { return length(p) - r; }",
            submodules: &[],
        }],
    },
    dependencies: &[],
};

fn main() {
    App::new()
        // Packages are read when the plugin is added, so insert the config first.
        .insert_resource(WispConfig {
            wesl_packages: vec![&SHAPES],
            ..default()
        })
        .add_plugins((
            DefaultPlugins.set(WindowPlugin {
                primary_window: Some(Window {
                    title: String::from("bevy_wisp - wesl"),
                    ..default()
                }),
                ..default()
            }),
            WispPlugin,
        ))
        .add_systems(Startup, setup)
        .run();
}

fn setup(mut commands: Commands, asset_server: Res<AssetServer>) {
    let wisp: Handle<Wisp> = asset_server.load("wisp/test_wesl.wesl");
    commands.spawn((Camera3d::default(), WispHandle(wisp)));
}
